/*Query 5 — Monthly Sales Trend
Business Problem

The CEO wants to understand how sales change over time.*/


SELECT 
    d.year,
    d.month,
    SUM(f.sales_amount) AS monthly_revenue,
    SUM(f.profit) AS profit
FROM fact_sales f
JOIN dim_date d ON f.date_id = d.date_id
GROUP BY 
    d.year,
    d.month
ORDER BY 
    d.year,
    d.month;



